// گام ۱ — بررسی توکن و آماده‌کردن درخواست embedding برای پرسش کاربر.
const req = $input.first().json;
if (!$env.AGENT_TOKEN || (req.headers || {})['x-agent-token'] !== $env.AGENT_TOKEN) {
  throw new Error('Unauthorized: invalid X-Agent-Token');
}
const question = String((req.body || {}).question || '').trim();
if (!question) throw new Error('question is empty');

return [{ json: { question, embed_request: { model: $env.EMBEDDING_MODEL, input: [question] } } }];

// گام ۳ — ساخت درخواست جست‌وجو در پایگاه دانش برداری پورتال (pgvector).
const res = $input.first().json;
const vector = res.data && res.data[0] && res.data[0].embedding;
if (!Array.isArray(vector)) {
  throw new Error('Embedding API returned no vector: ' + JSON.stringify(res).slice(0, 300));
}
return [{ json: { search_request: { embedding: vector, model: $env.EMBEDDING_MODEL, k: 5 } } }];

// گام ۵ — ساخت پرامپت «فقط بر اساس بندهای بازیابی‌شده پاسخ بده».
const question = $('Prepare Question').first().json.question;
const chunks = $input.first().json.chunks || [];

const context = chunks
  .map((c, i) => `[${i + 1}] (${c.doc}${c.ref ? ' — ' + c.ref : ''})\n${c.text}`)
  .join('\n\n');

const system = [
  'تو دستیار پاسخ‌گویی به پرسش‌های آیین‌نامه‌ای پروژه‌ی کارشناسی در دانشگاه صنعتی امیرکبیر هستی.',
  'فقط و فقط بر اساس «بندهای مرجع» که در پیام کاربر آمده پاسخ بده.',
  'قواعد:',
  '۱. پاسخ کوتاه، دقیق و به زبان فارسی باشد.',
  '۲. پس از هر مطلبی که از یک بند گرفته‌ای، شماره‌ی همان بند را به شکل [1] یا [2] بیاور.',
  '۳. اگر پاسخ در بندهای مرجع نیست، فقط بنویس: «در اسناد نمایه‌شده پاسخی برای این پرسش پیدا نکردم.» و چیزی از دانسته‌های خودت اضافه نکن.',
  '۴. تصمیم اداری یا علمی نگیر و وعده نده؛ فقط متن آیین‌نامه را توضیح بده.',
].join('\n');

return [
  {
    json: {
      question,
      sources: chunks.map((c, i) => ({ n: i + 1, chunk_id: c.id, score: c.score })),
      llm_request: {
        model: $env.LLM_CHAT_MODEL,
        temperature: 0,
        stream: false,
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: `بندهای مرجع:\n${context}\n\nپرسش: ${question}` },
        ],
      },
    },
  },
];

// گام ۷ — پاسخ نهایی برای پورتال: متن پاسخ + بندهای بازیابی‌شده (و این‌که کدام‌ها استناد شده‌اند).
const prompt = $('Build Prompt').first().json;
const res = $input.first().json;
const content = res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
if (!content) throw new Error('LLM returned no answer: ' + JSON.stringify(res).slice(0, 300));

const FA_DIGITS = '۰۱۲۳۴۵۶۷۸۹';
const answer = String(content).replace(/<think>[\s\S]*?<\/think>/g, '').trim();
const cited = new Set();
for (const m of answer.matchAll(/\[([0-9۰-۹]+)\]/g)) {
  cited.add(Number(m[1].replace(/[۰-۹]/g, (d) => String(FA_DIGITS.indexOf(d)))));
}

return [
  {
    json: {
      answer,
      sources: prompt.sources.map((s) => ({ ...s, cited: cited.has(s.n) })),
      model: $env.LLM_CHAT_MODEL,
    },
  },
];

// نمایه‌سازی: پورتال قطعه‌های سند را می‌فرستد تا بردار معنایی‌شان را بگیرد.
const req = $input.first().json;
if (!$env.AGENT_TOKEN || (req.headers || {})['x-agent-token'] !== $env.AGENT_TOKEN) {
  throw new Error('Unauthorized: invalid X-Agent-Token');
}
const texts = (req.body || {}).texts;
if (!Array.isArray(texts) || !texts.length) throw new Error('texts must be a non-empty array');

return [{ json: { embed_request: { model: $env.EMBEDDING_MODEL, input: texts.map(String) } } }];

// بردارها را به همان ترتیب متن‌های ورودی برمی‌گرداند.
const res = $input.first().json;
if (!Array.isArray(res.data)) {
  throw new Error('Embedding API returned no vectors: ' + JSON.stringify(res).slice(0, 300));
}
const vectors = res.data
  .slice()
  .sort((a, b) => (a.index || 0) - (b.index || 0))
  .map((d) => d.embedding);

return [{ json: { model: $env.EMBEDDING_MODEL, vectors } }];
